// =====================================================================
// RECOVERY WEBHOOK SIGNATURE VERIFICATION - fail closed before work starts
// =====================================================================

const CLOCK_SKEW_SECONDS = 5 * 60;
const NONCE_TTL_SECONDS = 10 * 60;
const IDEMPOTENCY_TTL_SECONDS = 30 * 24 * 60 * 60;
const enc = new TextEncoder();

const input = $input.item;
const headers = input.json.headers || {};
const body = input.json.body;
const binary = input.binary || {};
const nowSeconds = Math.floor(Date.now() / 1000);

function fail(statusCode, reason) {
  console.warn('[Recovery Webhook] rejected | status:', statusCode, '| reason:', reason);
  return {
    json: {
      isVerified: false,
      isDuplicate: false,
      responseCode: statusCode,
      reason
    }
  };
}

function header(name, aliases = []) {
  const wanted = [name, ...aliases].map(x => x.toLowerCase());
  for (const [key, value] of Object.entries(headers)) {
    if (!wanted.includes(key.toLowerCase())) continue;
    if (Array.isArray(value)) return String(value[0] || '').trim();
    return String(value || '').trim();
  }
  return '';
}

function rawBodyUtf8() {
  const data = binary.data?.data;
  if (!data) return '';
  return Buffer.from(data, 'base64').toString('utf8');
}

function parseSecretMap(raw) {
  if (!raw) return {};
  try {
    return JSON.parse(raw);
  } catch (error) {
    console.error('[Recovery Webhook] invalid secret map JSON:', error.message);
    return {};
  }
}

function resolveTenantSecret(tenantId) {
  const normalized = tenantId.toLowerCase();
  const compact = normalized.replace(/-/g, '');
  const envKey = 'N8N_RECOVERY_WEBHOOK_API_KEY_' + tenantId.replace(/-/g, '_').toUpperCase();
  const secretMap = parseSecretMap($env.N8N_RECOVERY_WEBHOOK_SECRETS_JSON || $env.RECOVERY_WEBHOOK_SECRETS_JSON);
  return secretMap[tenantId]
    || secretMap[normalized]
    || secretMap[compact]
    || $env[envKey]
    || $env.N8N_RECOVERY_WEBHOOK_API_KEY
    || $env.RECOVERY_WEBHOOK_API_KEY
    || '';
}

async function hmacSha256Hex(secret, text) {
  if (globalThis.crypto?.subtle) {
    const key = await globalThis.crypto.subtle.importKey(
      'raw',
      enc.encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const signature = await globalThis.crypto.subtle.sign('HMAC', key, enc.encode(text));
    return [...new Uint8Array(signature)].map(b => b.toString(16).padStart(2, '0')).join('');
  }

  const nodeCrypto = require('crypto');
  return nodeCrypto.createHmac('sha256', secret).update(text, 'utf8').digest('hex');
}

function constantTimeEqual(a, b) {
  const left = String(a || '');
  const right = String(b || '');
  const max = Math.max(left.length, right.length);
  let diff = left.length ^ right.length;
  for (let i = 0; i < max; i++) {
    const l = i < left.length ? left.charCodeAt(i) : 0;
    const r = i < right.length ? right.charCodeAt(i) : 0;
    diff |= l ^ r;
  }
  return diff === 0;
}

function cleanup(cache) {
  for (const [key, entry] of Object.entries(cache)) {
    if (!entry || entry.expiresAt <= nowSeconds) delete cache[key];
  }
}

const signatureVersion = header('x-recovery-signature-version');
const providedSignature = header('x-recovery-signature');
const timestamp = header('x-recovery-timestamp');
const nonce = header('x-recovery-nonce');
const tenantId = header('x-recovery-tenant-id', ['x-recovery-tenantid']);
const abandonedCartId = header('x-recovery-abandoned-cart-id', ['x-recovery-abandonedcartid']);
const cartId = header('x-recovery-cart-id', ['x-recovery-cartid']);
const idempotencyKey = header('idempotency-key');

const required = {
  'X-Recovery-Signature-Version': signatureVersion,
  'X-Recovery-Signature': providedSignature,
  'X-Recovery-Timestamp': timestamp,
  'X-Recovery-Nonce': nonce,
  'X-Recovery-Tenant-Id': tenantId,
  'X-Recovery-Abandoned-Cart-Id': abandonedCartId,
  'X-Recovery-Cart-Id': cartId,
  'Idempotency-Key': idempotencyKey
};
const missing = Object.entries(required).filter(([, value]) => !value).map(([name]) => name);
if (missing.length > 0) return fail(401, 'Missing required headers: ' + missing.join(', '));
if (signatureVersion !== 'v1') return fail(401, 'Unsupported recovery signature version');
if (!/^sha256=[0-9a-fA-F]{64}$/.test(providedSignature)) return fail(401, 'Invalid recovery signature format');

const timestampSeconds = Number(timestamp);
if (!Number.isInteger(timestampSeconds)) return fail(401, 'Invalid recovery timestamp');
if (Math.abs(nowSeconds - timestampSeconds) > CLOCK_SKEW_SECONDS) return fail(401, 'Expired recovery webhook timestamp');

const rawBody = rawBodyUtf8();
if (!rawBody) return fail(401, 'Raw request body is required for signature verification');

let payload = body;
if (!payload || typeof payload !== 'object') {
  try {
    payload = JSON.parse(rawBody);
  } catch {
    return fail(400, 'Invalid JSON body');
  }
}

if (payload.tenantId !== tenantId) return fail(401, 'Tenant header does not match body');
if (payload.abandonedCartId !== abandonedCartId) return fail(401, 'Abandoned cart header does not match body');
if (payload.cartId !== cartId) return fail(401, 'Cart header does not match body');

const staticData = $getWorkflowStaticData('global');
staticData.recoveryNonceCache = staticData.recoveryNonceCache || {};
staticData.recoveryIdempotency = staticData.recoveryIdempotency || {};
cleanup(staticData.recoveryNonceCache);
cleanup(staticData.recoveryIdempotency);

const nonceKey = tenantId + ':' + nonce;
if (staticData.recoveryNonceCache[nonceKey]) return fail(401, 'Replay nonce rejected');

const tenantSecret = resolveTenantSecret(tenantId);
if (!tenantSecret) return fail(403, 'Tenant recovery webhook secret is not configured');

const canonicalPayload = [
  tenantId,
  abandonedCartId,
  cartId,
  timestamp,
  nonce,
  idempotencyKey,
  rawBody
].join('.');
const expectedSignature = 'sha256=' + await hmacSha256Hex(tenantSecret, canonicalPayload);
if (!constantTimeEqual(expectedSignature.toLowerCase(), providedSignature.toLowerCase())) {
  return fail(401, 'Recovery signature verification failed');
}

staticData.recoveryNonceCache[nonceKey] = { expiresAt: nowSeconds + NONCE_TTL_SECONDS };
const idempotencyCacheKey = tenantId + ':' + idempotencyKey;
const existingIdempotency = staticData.recoveryIdempotency[idempotencyCacheKey];
if (existingIdempotency && existingIdempotency.expiresAt > nowSeconds) {
  console.log('[Recovery Webhook] duplicate accepted idempotently | tenantId:', tenantId, '| idempotencyKey:', idempotencyKey);
  return {
    json: {
      isVerified: true,
      isDuplicate: true,
      responseCode: 200,
      reason: 'Duplicate recovery webhook accepted idempotently',
      payload,
      security: { tenantId, abandonedCartId, cartId, idempotencyKey }
    }
  };
}

staticData.recoveryIdempotency[idempotencyCacheKey] = {
  status: 'accepted',
  acceptedAt: nowSeconds,
  expiresAt: nowSeconds + IDEMPOTENCY_TTL_SECONDS
};

console.log('[Recovery Webhook] verified | tenantId:', tenantId, '| abandonedCartId:', abandonedCartId, '| cartId:', cartId);
return {
  json: {
    isVerified: true,
    isDuplicate: false,
    responseCode: 200,
    reason: 'Recovery webhook verified',
    payload,
    security: { tenantId, abandonedCartId, cartId, idempotencyKey }
  }
};

