// =====================================================================
// VALIDATION NODE - Fail-fast if required fields missing
// =====================================================================

const payload = $input.item.json.payload || $input.item.json.body;
const security = $input.item.json.security || null;

// Required fields
const requiredFields = [
  'tenantId',
  'abandonedCartId',
  'cartId',
  'phoneNumber',
  'recoveryLink',
  'firstMessageDelayMinutes',
  'secondMessageDelayMinutes',
  'workingHoursFrom',
  'workingHoursTo'
];

// Validate presence
const missingFields = requiredFields.filter(field => !payload[field]);

if (missingFields.length > 0) {
  return {
    json: {
      isValid: false,
      reason: `Missing required fields: ${missingFields.join(', ')}`,
      payload,
      security
    }
  };
}

// Validate phoneNumber format (E.164)
if (!payload.phoneNumber.startsWith('+')) {
  return {
    json: {
      isValid: false,
      reason: 'Phone number must be in E.164 format (start with +)',
      payload,
      security
    }
  };
}

// Validate delays
if (payload.firstMessageDelayMinutes < 0) {
  return {
    json: {
      isValid: false,
      reason: 'firstMessageDelayMinutes cannot be negative',
      payload,
      security
    }
  };
}

if (payload.secondMessageDelayMinutes < 0) {
  return {
    json: {
      isValid: false,
      reason: 'secondMessageDelayMinutes cannot be negative',
      payload,
      security
    }
  };
}

// All validations passed
console.log('[Phase3] Validation | PASSED | abandonedCartId:', payload.abandonedCartId);

return {
  json: {
    isValid: true,
    reason: 'All validations passed',
    payload,
    security
  }
};

// =====================================================================
// NORMALIZATION NODE - Produce canonical object
// =====================================================================

const payload = $input.item.json.payload;
const security = $input.item.json.security || null;

// Parse cart snapshot
const cartSnapshot = payload.cartSnapshot || {};
const items = cartSnapshot.items || [];
const cartTotal = cartSnapshot.total || 0;
const currency = cartSnapshot.currency || 'USD';
const itemCount = items.length;

// Parse working hours to minutes
const parseTime = (timeStr) => {
  const [hours, minutes] = timeStr.split(':').map(Number);
  return hours * 60 + minutes;
};

const workingFromMinutes = parseTime(payload.workingHoursFrom);
const workingToMinutes = parseTime(payload.workingHoursTo);

// Extract product names for message personalization
const productNames = items.slice(0, 3).map(item => item.name || 'Product').join(', ');
const hasMoreProducts = items.length > 3;

// Build canonical object
const normalized = {
  // IDs
  tenantId: payload.tenantId,
  abandonedCartId: payload.abandonedCartId,
  cartId: payload.cartId,

  // Contact
  phoneNumber: payload.phoneNumber,
  email: payload.email || null,

  // Cart data
  cartTotal,
  currency,
  itemCount,
  productNames,
  hasMoreProducts,

  // Recovery
  recoveryLink: payload.recoveryLink,

  // Timing
  firstDelay: payload.firstMessageDelayMinutes,
  secondDelay: payload.secondMessageDelayMinutes,
  workingFromMinutes,
  workingToMinutes,

  // Metadata
  triggeredAtUtc: payload.triggeredAtUtc || new Date().toISOString(),

  // Message tracking
  firstMessageSent: false,
  secondMessageSent: false,
  security
};

console.log('[Phase3] Normalization | COMPLETE | abandonedCartId:', normalized.abandonedCartId, '| itemCount:', normalized.itemCount);

return { json: normalized };

// =====================================================================
// WORKING HOURS GATE - Enforce working hours with overnight wrap support
// =====================================================================

const data = $input.item.json;

// Get current time in minutes since midnight
const now = new Date();
const currentMinutes = now.getHours() * 60 + now.getMinutes();

const workingFrom = data.workingFromMinutes;
const workingTo = data.workingToMinutes;

// Check if within working hours
let isWithinWorkingHours = false;
let delayMinutes = 0;

if (workingFrom <= workingTo) {
  // Normal case: 09:00 - 21:00
  isWithinWorkingHours = currentMinutes >= workingFrom && currentMinutes <= workingTo;

  if (!isWithinWorkingHours) {
    if (currentMinutes < workingFrom) {
      // Before working hours today
      delayMinutes = workingFrom - currentMinutes;
    } else {
      // After working hours today, wait until tomorrow
      delayMinutes = (24 * 60 - currentMinutes) + workingFrom;
    }
  }
} else {
  // Overnight case: 21:00 - 09:00 (next day)
  isWithinWorkingHours = currentMinutes >= workingFrom || currentMinutes <= workingTo;

  if (!isWithinWorkingHours) {
    // Between end and start (e.g., 09:00 - 21:00 when window is 21:00 - 09:00)
    delayMinutes = workingFrom - currentMinutes;
  }
}

const shouldDelay = delayMinutes > 0;

console.log('[Phase3] Working Hours Gate | abandonedCartId:', data.abandonedCartId, '| currentMinutes:', currentMinutes, '| isWithinWorkingHours:', isWithinWorkingHours, '| delayMinutes:', delayMinutes);

return {
  json: {
    ...data,
    isWithinWorkingHours,
    delayMinutes,
    shouldDelay
  }
};

