// =====================================================================
// FIRST MESSAGE RESULT HANDLER
// =====================================================================

const data = $input.item.json;
const error = $input.item.error;

let firstMessageSent = false;
let firstMessageError = null;

if (error) {
  console.error('[Phase3] First Message | FAILED | abandonedCartId:', data.abandonedCartId, '| error:', error.message);
  firstMessageError = error.message;
} else {
  console.log('[Phase3] First Message | SENT | abandonedCartId:', data.abandonedCartId);
  firstMessageSent = true;
}

return {
  json: {
    ...data,
    firstMessageSent,
    firstMessageError,
    firstMessageSentAt: new Date().toISOString()
  }
};

