// =====================================================================
// SECOND MESSAGE RESULT HANDLER
// =====================================================================

const data = $input.item.json;
const error = $input.item.error;

let secondMessageSent = false;
let secondMessageError = null;

if (error) {
  console.error('[Phase3] Second Message | FAILED | abandonedCartId:', data.abandonedCartId, '| error:', error.message);
  secondMessageError = error.message;
} else {
  console.log('[Phase3] Second Message | SENT | abandonedCartId:', data.abandonedCartId);
  secondMessageSent = true;
}

return {
  json: {
    ...data,
    secondMessageSent,
    secondMessageError,
    secondMessageSentAt: new Date().toISOString()
  }
};

// =====================================================================
// IDEMPOTENCY COMPLETION MARKER
// =====================================================================
const data = $input.item.json;
const security = data.security || {};
if (security.tenantId && security.idempotencyKey) {
  const staticData = $getWorkflowStaticData('global');
  staticData.recoveryIdempotency = staticData.recoveryIdempotency || {};
  const key = security.tenantId + ':' + security.idempotencyKey;
  const existing = staticData.recoveryIdempotency[key];
  if (existing) {
    existing.status = 'processed';
    existing.processedAt = Math.floor(Date.now() / 1000);
  }
}
return { json: data };

// =====================================================================
// WORKFLOW COMPLETE
// =====================================================================

const data = $input.item.json;

console.log('[Phase3] Workflow Complete | abandonedCartId:', data.abandonedCartId, '| firstMessageSent:', data.firstMessageSent, '| secondMessageSent:', data.secondMessageSent || false);

return {
  json: {
    success: true,
    abandonedCartId: data.abandonedCartId,
    firstMessageSent: data.firstMessageSent,
    secondMessageSent: data.secondMessageSent || false,
    completedAt: new Date().toISOString()
  }
};
